#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT_LEN 1024

int main(int argc, char **argv) {
    if (argc <= 1) return 0;
    const char *src = argv[1];
    size_t src_len = strlen(src);
    if (src_len > MAX_INPUT_LEN) {
        puts("TOO_LONG");
        return 0;
    }
    char norm[MAX_INPUT_LEN + 1];
    size_t n = 0;
    for (size_t i = 0; i < src_len; ++i) {
        unsigned char c = (unsigned char)src[i];
        if (c >= 'A' && c <= 'Z') c = c + 0x20;
        if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
            norm[n++] = (char)c;
        }
    }
    norm[n] = '\0';
    int is_pal = 1;
    for (size_t i = 0; i < n/2; ++i) {
        if (norm[i] != norm[n-1-i]) { is_pal = 0; break; }
    }
    puts(is_pal ? "PALINDROME" : "NOT_PALINDROME");
    return 0;
}
